"""Owner source admission supported by a complete, bound empirical qualification.

Eligibility is a reviewed source-level decision, not an outcome filter or a claim
of universal optimality. Original rewards remain unchanged. This module does not
authenticate policy artifacts, native tokens, serving identity or launch authority.
"""

from __future__ import annotations

import copy
import math

from .reward_qualification import _SCORED_STATUSES, REQUIRED_COVERAGE, _hash

VERSION = "ndfeb-empirical-reward-qualification-v2"
CASE_KEYS = frozenset({"revision_off690_peak", "retention_resolvable", "ambiguity",
                       "nonidentifiability"})
EVIDENCE_KEYS = ("design", "manifest", "analysis", "independent_audit", "source_decision")


def _identities(rows, *, case_field, errors, label):
    result = {}
    if not isinstance(rows, list):
        errors.append(label + ":missing_rows")
        return result
    for row in rows:
        if (not isinstance(row, dict) or not isinstance(row.get(case_field), str)
                or not row[case_field] or not isinstance(row.get("arm"), str) or not row["arm"]):
            errors.append(label + ":malformed_identity")
            continue
        key = row[case_field] + "/" + row["arm"]
        if key in result:
            errors.append(label + ":duplicate_identity")
        result[key] = row
    return result


def _same_ids(value, expected):
    return (isinstance(value, list) and all(isinstance(item, str) for item in value)
            and len(value) == len(expected) and set(value) == expected)


def _evidence_errors(evidence):
    """Check completeness and identity, without requiring favorable outcomes."""
    errors = []
    if not isinstance(evidence, dict) or any(not isinstance(evidence.get(k), dict)
                                            for k in EVIDENCE_KEYS):
        return ["qualification_evidence:missing_object"]
    design, manifest, analysis, audit = (evidence[k] for k in EVIDENCE_KEYS[:-1])
    if design.get("schema") != "ndfeb-evidence-value-design-v1":
        errors.append("qualification_design_schema")
    if manifest.get("schema") != "ndfeb-evidence-value-qualification-v1":
        errors.append("qualification_manifest_schema")
    if analysis.get("schema") != "ndfeb-evidence-value-analysis-v1":
        errors.append("qualification_analysis_schema")
    if audit.get("schema") != "independent-evidence-control-audit-v1":
        errors.append("qualification_audit_schema")
    arms = manifest.get("arms", {})
    cases = manifest.get("cases", [])
    if not isinstance(arms, dict) or not arms or not isinstance(cases, list):
        return errors + ["qualification_manifest_schedule"]
    case_index = {}
    for case in cases:
        if (not isinstance(case, dict) or not isinstance(case.get("id"), str)
                or not case["id"] or not isinstance(case.get("world_key"), str)
                or case["world_key"] not in CASE_KEYS
                or case["id"] in case_index):
            errors.append("qualification_manifest_case_identity")
            continue
        case_index[case["id"]] = case
    expected = {case + "/" + arm for case in case_index for arm in arms}
    replication = design.get("replication", {})
    if not isinstance(replication, dict):
        replication = {}
    design_arms = design.get("arms")
    if (len(expected) != 240 or replication.get("planned_episodes") != len(expected)
            or replication.get("case_count") != len(case_index)
            or replication.get("arm_count") != len(arms)
            or not isinstance(design_arms, dict) or set(design_arms) != set(arms)
            or {case["world_key"] for case in case_index.values()} != CASE_KEYS):
        errors.append("qualification_planned_schedule_changed")
    if manifest.get("reward_changed") is not False or manifest.get("scientific_body_allowance") != 24:
        errors.append("qualification_mission_or_body_budget_changed")
    for key in ("expected_episode_ids", "committed_episode_ids", "assessed_episode_ids"):
        if not _same_ids(analysis.get(key), expected):
            errors.append("qualification_analysis:" + key)
    if (analysis.get("planned_episodes") != len(expected)
            or analysis.get("recorded_episodes") != len(expected)
            or analysis.get("missing_assessment_episode_ids") != []):
        errors.append("qualification_analysis_incomplete")
    analyzed = _identities(analysis.get("seed_level_rows"), case_field="case_id",
                           errors=errors, label="qualification_analysis")
    if set(analyzed) != expected:
        errors.append("qualification_analysis_row_coverage")
    for row in analyzed.values():
        case = case_index.get(row["case_id"])
        if case is None or any(row.get(k) != case.get(k) for k in ("world_key", "seed", "seed_index")):
            errors.append("qualification_analysis_source_identity")
    audited = _identities(audit.get("episodes"), case_field="case", errors=errors,
                          label="qualification_audit")
    if (audit.get("status") != "passed" or audit.get("failures") != []
            or audit.get("planned_episodes") != len(expected) or set(audited) != expected
            or any(row.get("complete") is not True for row in audited.values())):
        errors.append("qualification_independent_audit_incomplete_or_failed")
    return errors


def validate_registry(registry, *, worlds, public_task, reward_contract, qualification_evidence):
    """Validate the pinned registry and complete empirical evidence supplied by owner."""
    errors = _evidence_errors(qualification_evidence)
    if not isinstance(registry, dict) or not isinstance(worlds, dict):
        return {"schema": VERSION, "valid": False, "decision_approved": False,
                "errors": errors + ["registry_and_worlds_must_be_objects"],
                "status": "blocked_qualification_binding"}
    if registry.get("schema") != VERSION or registry.get("status") != "complete":
        errors.append("qualification_registry_incomplete_or_wrong_schema")
    if _hash(registry) is None:
        errors.append("registry_not_finite_json")
    bindings = registry.get("bindings", {})
    bindings = bindings if isinstance(bindings, dict) else {}
    values = {"worlds": worlds, "public_task": public_task, "reward_contract": reward_contract}
    values.update({key: qualification_evidence.get(key) if isinstance(qualification_evidence, dict)
                   else None for key in EVIDENCE_KEYS})
    for name, value in values.items():
        actual = _hash(value) if isinstance(value, dict) else None
        if actual is None or bindings.get(name + "_sha256") != actual:
            errors.append("binding:" + name)
    cases = registry.get("cases", {})
    cases = cases if isinstance(cases, dict) else {}
    if set(worlds) != CASE_KEYS or set(cases) != CASE_KEYS:
        errors.append("frozen_family_case_set")
    if not _same_ids(registry.get("required_decision_coverage"), REQUIRED_COVERAGE):
        errors.append("required_decision_coverage")
    planned = registry.get("planned_source_keys")
    if (not isinstance(planned, list) or not planned or not all(isinstance(k, str) for k in planned)
            or len(planned) != len(set(planned)) or not set(planned) <= CASE_KEYS):
        errors.append("planned_source_keys")
    for key in CASE_KEYS:
        entry = cases.get(key)
        if not isinstance(entry, dict):
            errors.append("case_entry:" + key)
            continue
        if not isinstance(worlds.get(key), dict) or entry.get("world_sha256") != _hash(worlds[key]):
            errors.append("world_binding:" + key)
        if type(entry.get("optimization_qualified")) is not bool:
            errors.append("case_eligibility:" + key)
        coverage = entry.get("decision_coverage")
        if (not isinstance(coverage, list) or not all(isinstance(c, str) for c in coverage)
                or len(coverage) != len(set(coverage)) or not set(coverage) <= REQUIRED_COVERAGE
                or (entry.get("optimization_qualified") is True and not coverage)):
            errors.append("case_decision_coverage:" + key)
        if any(not isinstance(entry.get(k), str) or not entry[k].strip() for k in ("scope", "reason")):
            errors.append("case_scope_or_reason:" + key)
    decision = values.get("source_decision")
    decision = decision if isinstance(decision, dict) else {}
    if (decision.get("status") not in ("approved", "blocked")
            or not isinstance(decision.get("reason"), str) or not decision["reason"].strip()
            or decision.get("cases") != cases or decision.get("planned_source_keys") != planned):
        errors.append("final_source_decision")
    decision_bindings = decision.get("evidence_sha256s", {})
    decision_bindings = decision_bindings if isinstance(decision_bindings, dict) else {}
    for key in EVIDENCE_KEYS[:-1]:
        if decision_bindings.get(key) != _hash(values.get(key)):
            errors.append("final_source_decision_evidence:" + key)
    rule = values.get("analysis", {}).get("frozen_signal_rule", {}) if isinstance(values.get("analysis"), dict) else {}
    rule = rule if isinstance(rule, dict) else {}
    criterion_met = any(isinstance(rule.get(method), dict)
                        and rule[method].get("frozen_useful_evidence_criterion_met") is True
                        for method in ("descriptor_full", "raw_full"))
    if decision.get("status") == "approved" and not criterion_met:
        errors.append("approved_decision_disagrees_with_frozen_signal_rule")
    approved = not errors and decision.get("status") == "approved"
    return {"schema": VERSION, "valid": not errors, "decision_approved": approved,
            "errors": errors, "registry_sha256": _hash(registry),
            "status": "registry_bound" if approved else "blocked_scientific_qualification",
            "authentication_performed": False, "training_authorized": False}


def admit_case(case_key, registry, **inputs):
    """Apply the reviewed source decision before generation or source derivation."""
    validation = validate_registry(registry, **inputs)
    known = isinstance(case_key, str) and case_key in CASE_KEYS
    entry = registry["cases"][case_key] if validation["valid"] and known else {}
    qualified = validation["decision_approved"] and known and entry.get("optimization_qualified") is True
    return {"schema": VERSION, "case_key": case_key, "optimization_qualified": qualified,
            "status": "source_qualified" if qualified else "blocked_scientific_qualification",
            "reason": entry.get("reason", "unknown_case_or_incomplete_qualification"),
            "scope": entry.get("scope"), "decision_coverage": entry.get("decision_coverage", []),
            "registry_sha256": validation.get("registry_sha256"), "validation": validation}


def overlay_assessment(result, *, case_key, registry, **inputs):
    """Preserve the original authenticated result; add no behavioral reward terms."""
    admission = admit_case(case_key, registry, **inputs)
    original = copy.deepcopy(result)
    status = original.get("status") if isinstance(original, dict) else None
    reward = original.get("reward") if isinstance(original, dict) else None
    expected = _SCORED_STATUSES.get(status) if isinstance(status, str) else None
    category = expected[1] if expected else (
        "unfinished" if status == "awaiting_external_evidence" else
        "unresolved_nomination" if status == "numerical_boundary_unresolved" else "unavailable")
    label_valid = (expected is not None and type(reward) in (int, float) and math.isfinite(reward)
                   and reward == expected[0] and original.get("contract_sha256") == _hash(inputs["reward_contract"]))
    if case_key == "nonidentifiability" and status in (
            "supported_advancement", "certified_reference_retention", "wrong_retention"):
        # These labels contradict the unchanged missing-grain reward evaluator;
        # this is owner-record consistency, not an empirical source exclusion.
        label_valid = False
    eligible = admission["optimization_qualified"] and label_valid
    return {"schema": VERSION, "case_key": case_key, "original_assessment": original,
            "original_status": status, "original_reward": reward, "action_category": category,
            "optimizer_reward": reward if eligible else None, "optimization_eligible": eligible,
            "owner_label_well_formed": label_valid, "source_admission": admission,
            "episode_denominator": 1, "authentication_performed": False,
            "five_behavioral_axes_used_as_reward": False}


def admit_schedule(schedule, registry, *, results=None, **inputs):
    """Require every planned source and complete result groups, including failures."""
    validation = validate_registry(registry, **inputs)
    errors = list(validation["errors"])
    if not validation["decision_approved"]:
        errors.append("scientific_source_decision_not_approved")
    rows = schedule if isinstance(schedule, list) else []
    if not rows:
        errors.append("nonempty_predeclared_schedule_required")
    indexed, coverage, admissions = {}, set(), []
    for row in rows:
        if (not isinstance(row, dict) or not isinstance(row.get("episode_id"), str)
                or not row["episode_id"] or not isinstance(row.get("case_key"), str)):
            errors.append("malformed_schedule_identity")
            continue
        key = row["episode_id"]
        if key in indexed:
            errors.append("duplicate_scheduled_episode:" + key)
            continue
        indexed[key] = row["case_key"]
        admitted = admit_case(row["case_key"], registry, **inputs)
        admissions.append({"episode_id": key, **admitted})
        if not admitted["optimization_qualified"]:
            errors.append("unqualified_scheduled_source:" + key)
        else:
            coverage.update(admitted["decision_coverage"])
    planned = registry.get("planned_source_keys", []) if isinstance(registry, dict) else []
    if not _same_ids(planned, set(indexed.values())):
        errors.append("whole_planned_source_coverage")
    missing = sorted(REQUIRED_COVERAGE - coverage)
    if missing:
        errors.append("missing_qualified_decision_coverage:" + ",".join(missing))
    overlays = []
    if results is not None:
        found = set()
        for row in results if isinstance(results, list) else []:
            if (not isinstance(row, dict) or not isinstance(row.get("episode_id"), str)
                    or row["episode_id"] not in indexed or row["episode_id"] in found
                    or row.get("case_key") != indexed[row["episode_id"]]):
                errors.append("result_identity_mismatch_or_duplicate")
                continue
            found.add(row["episode_id"])
            overlay = overlay_assessment(row.get("assessment"), case_key=row["case_key"],
                                         registry=registry, **inputs)
            overlays.append({"episode_id": row["episode_id"], **overlay})
            if not overlay["owner_label_well_formed"]:
                errors.append("missing_or_unverified_owner_label:" + row["episode_id"])
        if found != set(indexed):
            errors.append("result_coverage_mismatch")
    return {"schema": VERSION, "training_admissible": not errors,
            "status": "admissible" if not errors else "blocked_scientific_qualification",
            "errors": errors, "planned_episode_count": len(rows),
            "result_count": None if results is None else len(results) if isinstance(results, list) else 0,
            "required_decision_coverage": sorted(REQUIRED_COVERAGE),
            "qualified_decision_coverage": sorted(coverage), "missing_decision_coverage": missing,
            "source_admissions": admissions, "assessment_overlays": overlays,
            "registry_sha256": validation.get("registry_sha256"),
            "authentication_performed": False, "training_authorized": False}
